import {state} from './store.js';
export const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={home:'M3 10 12 3l9 7v10h-6v-7H9v7H3Z',learn:'M5 3v18M5 5h11l-2 4 2 4H5',practice:'m13 2-9 12h7l-1 8L21 9h-8Z',phrasebook:'M3 5q5-2 9 1 4-3 9-1v15q-5-2-9 1-4-3-9-1ZM12 6v15',alphabet:'m3 20 7-16h3l7 16M6 14h11',grammar:'M5 3h14v18H5ZM9 7h6M9 11h6M9 15h4',stats:'M4 20h17M7 16v-5M12 16V4M17 16V8',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8ZM9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1Z',arrow:'M5 12h14m-5-5 5 5-5 5',audio:'M4 9h4l5-4v14l-5-4H4Zm13-2q5 5 0 10M16 10q2 2 0 4',leaf:'M5 20q-4-14 14-16 2 16-11 13M5 20 15 9',star:'m12 3 3 6 7 1-5 5 1 7-6-3-6 3 1-7-5-5 7-1Z',check:'m5 12 4 4L20 5',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18ZM12 7v6l4 2',fire:'M12 2q0 6 5 8 6 9-5 12-12-3-5-12 0 4 3 3 3-4 2-11Z',shield:'m12 3 8 3v6q-1 7-8 10-7-3-8-10V6Z'};
export const icon=n=>`<svg class="icon" aria-hidden="true" viewBox="0 0 24 24"><path d="${paths[n]||paths.leaf}"/></svg>`;
export function target(item,language,cls='target'){const text=language.code==='ar'&&!state().settings.diacritics?item.targetNoDiacritics||item.target:item.target;return `<bdi class="${cls}" dir="${language.direction}" lang="${language.code}">${esc(text)}</bdi>`;}
export const audioButtons=id=>`<span class="audio"><button type="button" data-audio="${esc(id)}" aria-label="Play pronunciation">${icon('audio')}</button><button type="button" data-audio="${esc(id)}" data-slow="1" aria-label="Play pronunciation slowly">🐢<span class="sr-only">Slow</span></button></span>`;
let toastTimer;
export function toast(message){const el=document.querySelector('#toast');el.textContent=message;clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.textContent='',7000);}
export function modal(html){document.querySelector('#modal-content').innerHTML=html;document.querySelector('#modal').showModal();}
export const heading=(title,description,aside='')=>`<div class="heading"><div><h1>${title}</h1><p>${description}</p></div>${aside}</div>`;
export function plant(){return `<svg class="hero-art" viewBox="0 0 240 240" fill="none" aria-hidden="true"><circle cx="129" cy="110" r="95" fill="#dfe8cb"/><path d="M19 171h28M199 45h15M207 38v14" stroke="#a8bb84" stroke-width="2"/><path d="M37 194 62 150l95 30-13 36Z" fill="#cba96e"/><path d="m37 194 104 25 8-12-104-24Z" fill="#f2ddad"/><path d="m56 177 22-43 108 20-20 46Z" fill="#5c7e52"/><path d="m56 177 109 23 7-12-110-23Z" fill="#faf3d7"/><path d="m75 157 12-38 111 13-12 36Z" fill="#a5b492"/><path d="m75 157 111 11 3-12-111-11Z" fill="#f5edcd"/><path d="M135 138V69" stroke="#486b39" stroke-width="4"/><path d="M135 111q-54-4-47-42 45 0 47 42Z" fill="#73945a"/><path d="M136 92q-4-41 37-48 8 36-37 48Z" fill="#426d45"/><path d="M135 75q-30-13-20-42 30 10 20 42Z" fill="#91aa68"/><path d="M109 126h51l-8 32h-35Z" fill="#d2a278"/><path d="M105 122h59v9h-59Z" fill="#e2b68a"/><path d="m173 101 7-15 8 15-8 8Z" fill="#e9be66"/><circle cx="59" cy="65" r="4" fill="#a6b68b"/><path d="M209 191q-20-12-27 1" stroke="#a5b78b" stroke-width="2"/><path d="m35 108 5-6 5 6-5 6Z" fill="#d6b66f"/></svg>`;}
